export function disputePageT(
  lang: AppLanguage,
  key: DisputePageMessageKey,
  vars?: Record<string, string | number>,
): string {
  const raw = DISPUTE_PAGE_MESSAGES[lang]?.[key] ?? DISPUTE_PAGE_MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
